SourceCode.Declaration:
/// <summary>
/// <c>METPrintDestinationContract</c> contract class to open common parameter and print destination dialog form
/// </summary>
[DataContractAttribute]
public class METPrintDestinationContract
{
    container       recordCon;
    boolean         usePrintMgmt;
    str             menuItemName;

}

Method.Source:
/// <summary>
/// container holds the list of records
/// </summary>
/// <param name = "_recordCon">container</param>
/// <returns>container</returns>
[DataMemberAttribute, 
    SysOperationControlVisibilityAttribute(false)]
public container parmRecordCon(container _recordCon = recordCon)
{
    recordCon = _recordCon;

    return recordCon;
}

/// <summary>
/// MenuitemName
/// </summary>
/// <param name = "_menuItemName">str</param>
/// <returns>str</returns>
[DataMemberAttribute,
    SysOperationControlVisibilityAttribute(false)]
public str parmMenuItemName(str _menuItemName = menuItemName)
{
    menuItemName = _menuItemName;

    return menuItemName;
}

/// <summary>
/// method to set or get use print management
/// </summary>
/// <param name = "_usePrintMgmt">boolean</param>
/// <returns>boolean</returns>
[DataMemberAttribute, SysOperationLabel('Use print management destination'),
    SysOperationControlVisibilityAttribute(true)]
public boolean parmUsePrintMgmt(boolean _usePrintMgmt = usePrintMgmt)
{
    usePrintMgmt = _usePrintMgmt;

    return usePrintMgmt;
}
